/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: mount, card, paneTone, settle, rest, pointerOver, focusWithoutVisibleFocus
 *   Constants: sample, palette, cardNames
 *   Variables: nextId
 * Tests
 *   - samples a card once the pointer rests on it and returns to neutral after leaving the cards
 *   - a quick sweep across a shelf samples only the card the pointer stops on
 *   - applies an already sampled tone at once
 *   - follows visible keyboard focus and keeps the focused card tone after the pointer leaves
 *   - focus from a tap or click never tints the pane, including after the pointer leaves
 *   - ignores touch pointers and a tone that resolves after the pointer moved on
 *   - clears the main-pane tone on unmount and ignores samples that finish afterwards
 * @end-catalog */

import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';

import { sampleArtworkTone } from '../../artwork/artworkTone';
import { neutralArtworkTone } from '../../artwork/useArtworkTone';
import { useCardHoverTone } from './useCardHoverTone';

vi.mock('../../artwork/artworkTone', () => ({ sampleArtworkTone: vi.fn() }));

const sample = vi.mocked(sampleArtworkTone);
const palette = [
  { hero: '#7a1f2b', pane: '#4f141c' },
  { hero: '#1f4f7a', pane: '#16384f' },
  { hero: '#2f6a2a', pane: '#1f4a1c' },
  { hero: '#6a4f1f', pane: '#4a3714' }
];
const [red, blue, green, amber] = palette;
const cardNames = ['First', 'Second', 'Third', 'Fourth'];
// Tones are cached per image id for the whole file, so each test mounts cards with fresh ids.
let nextId = 0;

const mount = () => {
  const sources = palette.map(() => `/content/images/${String(++nextId).padStart(24, '0')}`);
  const tones = new Map(sources.map((source, index) => [`${source}/v1/96.webp`, palette[index]]));
  sample.mockImplementation(async (url) => tones.get(url) ?? null);

  const Cards = () => (
    <div {...useCardHoverTone()}>
      {sources.map((source, index) => (
        <article data-artwork-src={source} key={source}><button type="button">{cardNames[index]}</button></article>
      ))}
      <article><button type="button">No artwork</button></article>
      <p>Section copy</p>
    </div>
  );
  const main = document.createElement('main');
  main.id = 'main-content';
  document.body.append(main);
  return { sources, ...render(<Cards />, { container: main }) };
};

const card = (name: string) => screen.getByRole('button', { name });
const paneTone = () => document.getElementById('main-content')?.style.getPropertyValue('--tone-color');
const settle = () => act(async () => { await vi.dynamicImportSettled(); });
const rest = async (ms = 150) => {
  act(() => { vi.advanceTimersByTime(ms); });
  await settle();
};

/** jsdom has no PointerEvent, so set pointerType on a plain event that React still reads. */
const pointerOver = (target: Element, pointerType = 'mouse') => {
  const event = new MouseEvent('pointerover', { bubbles: true });
  Object.defineProperty(event, 'pointerType', { value: pointerType });
  fireEvent(target, event);
};

/** jsdom matches :focus-visible for any focus; this models a tap or click that focuses without it. */
const focusWithoutVisibleFocus = () => {
  const matches = Element.prototype.matches;
  vi.spyOn(Element.prototype, 'matches').mockImplementation(function (this: Element, selector: string) {
    return selector === ':focus-visible' ? false : matches.call(this, selector);
  });
};

beforeEach(() => {
  vi.useFakeTimers();
});

afterEach(() => {
  cleanup();
  vi.useRealTimers();
  document.body.innerHTML = '';
});

test('samples a card once the pointer rests on it and returns to neutral after leaving the cards', async () => {
  mount();
  expect(paneTone()).toBe(neutralArtworkTone.pane);

  pointerOver(card('First'));
  await rest(149);
  expect(sample).not.toHaveBeenCalled();
  await rest(1);
  expect(paneTone()).toBe(red.pane);

  // Crossing the gap to the next card does not flash the neutral tone.
  pointerOver(screen.getByText('Section copy'));
  await rest(100);
  pointerOver(card('Second'));
  await rest();
  expect(paneTone()).toBe(blue.pane);

  pointerOver(card('No artwork'));
  await rest(149);
  expect(paneTone()).toBe(blue.pane);
  await rest(1);
  expect(paneTone()).toBe(neutralArtworkTone.pane);
});

test('a quick sweep across a shelf samples only the card the pointer stops on', async () => {
  const { sources } = mount();
  for (const name of cardNames) {
    pointerOver(card(name));
    await rest(60);
  }
  await rest();

  expect(sample).toHaveBeenCalledTimes(1);
  expect(sample).toHaveBeenCalledWith(`${sources[3]}/v1/96.webp`);
  expect(paneTone()).toBe(amber.pane);
});

test('applies an already sampled tone at once', async () => {
  mount();
  pointerOver(card('Third'));
  await rest();
  pointerOver(card('No artwork'));
  await rest();
  expect(paneTone()).toBe(neutralArtworkTone.pane);

  pointerOver(card('Third'));
  await settle();
  expect(paneTone()).toBe(green.pane);
  expect(sample).toHaveBeenCalledTimes(1);
});

test('follows visible keyboard focus and keeps the focused card tone after the pointer leaves', async () => {
  mount();
  const first = card('First');

  act(() => first.focus());
  await rest();
  expect(paneTone()).toBe(red.pane);

  pointerOver(card('Second'));
  await rest();
  expect(paneTone()).toBe(blue.pane);
  fireEvent.pointerLeave(first.closest('div')!);
  await rest();
  expect(paneTone()).toBe(red.pane);

  act(() => card('No artwork').focus());
  await rest();
  expect(paneTone()).toBe(neutralArtworkTone.pane);
});

test('focus from a tap or click never tints the pane, including after the pointer leaves', async () => {
  focusWithoutVisibleFocus();
  mount();

  act(() => card('First').focus());
  await rest();
  expect(paneTone()).toBe(neutralArtworkTone.pane);
  expect(sample).not.toHaveBeenCalled();

  pointerOver(card('Second'));
  await rest();
  expect(paneTone()).toBe(blue.pane);
  act(() => card('Second').focus());
  fireEvent.pointerLeave(card('Second').closest('div')!);
  await rest();
  expect(paneTone()).toBe(neutralArtworkTone.pane);
});

test('ignores touch pointers and a tone that resolves after the pointer moved on', async () => {
  const { sources } = mount();
  let finishFirst!: (tone: typeof red) => void;
  const resolveTone = sample.getMockImplementation()!;
  sample.mockImplementation((url) => url.startsWith(sources[0])
    ? new Promise((resolve) => { finishFirst = resolve; })
    : resolveTone(url));

  pointerOver(card('Second'), 'touch');
  await rest();
  expect(paneTone()).toBe(neutralArtworkTone.pane);
  expect(sample).not.toHaveBeenCalled();

  pointerOver(card('First'));
  await rest();
  pointerOver(card('Second'));
  await rest();
  await act(async () => finishFirst(red));
  expect(paneTone()).toBe(blue.pane);
});

test('clears the main-pane tone on unmount and ignores samples that finish afterwards', async () => {
  const { unmount } = mount();
  let finish!: (tone: typeof red) => void;
  sample.mockImplementation(() => new Promise((resolve) => { finish = resolve; }));

  pointerOver(card('First'));
  await rest();
  unmount();
  expect(paneTone()).toBe('');
  await act(async () => finish(red));
  expect(paneTone()).toBe('');
});
